src/PhpStan/Rule/Architecture/ForbiddenFileTermInspector.php
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Architecture;

use function file;
use function is_array;

use PHPStan\Rules\IdentifierRuleError;

use function sprintf;
use function stripos;
use function strtolower;

use Toolkit\PhpStan\Rule\Shared\LineOrderedErrors;

/**
 * Finds forbidden literal terms in every kind of source text in restricted files.
 */
final class ForbiddenFileTermInspector
{
    /** @readonly */
    private ForbiddenFileTermErrorBuilder $errorBuilder;

    /** @readonly */
    private LineOrderedErrors $lineOrderedErrors;

    /**
     * Creates an inspector from restrictions and error reporting services.
     */
    public function __construct(
        private ForbiddenFileTermRestrictions $restrictions,
        ?ForbiddenFileTermErrorBuilder $errorBuilder = null,
        ?LineOrderedErrors $lineOrderedErrors = null,
    ) {
        $this->errorBuilder = $errorBuilder ?? new ForbiddenFileTermErrorBuilder();
        $this->lineOrderedErrors = $lineOrderedErrors ?? new LineOrderedErrors();
    }

    /**
     * Returns one error per forbidden term and source line.
     *
     * @return list<IdentifierRuleError>
     */
    public function errors(string $filePath): array
    {
        $restrictions = $this->restrictions->matching($filePath);
        if ($restrictions === []) {
            return [];
        }

        $lines = @file($filePath, FILE_IGNORE_NEW_LINES);
        if (!is_array($lines)) {
            return [];
        }

        $errors = [];
        $reported = [];
        foreach ($lines as $index => $line) {
            $lineNumber = $index + 1;
            foreach ($restrictions as $restriction) {
                foreach ($restriction['terms'] as $term) {
                    $reportKey = sprintf('%d:%s', $lineNumber, strtolower($term));
                    if (isset($reported[$reportKey]) || stripos($line, $term) === false) {
                        continue;
                    }

                    $reported[$reportKey] = true;
                    $errors[] = $this->errorBuilder->build($term, $restriction['path'], $lineNumber);
                }
            }
        }

        return $this->lineOrderedErrors->sorted($errors);
    }
}
src/PhpStan/Rule/Architecture/ForbiddenFileTermRestrictions.php
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Architecture;

use function strtolower;

use Toolkit\PhpStan\Rule\Shared\Path\RulePathMatcher;

/**
 * Holds normalized path-specific forbidden-term policies.
 */
final class ForbiddenFileTermRestrictions
{
    /**
     * @var list<array{path: string, terms: list<string>, matcher: RulePathMatcher}>
     */
    private array $restrictions = [];

    /**
     * @param array<string, list<string>> $forbiddenTermsByPath path patterns mapped to literal forbidden terms
     */
    public function __construct(array $forbiddenTermsByPath = [])
    {
        foreach ($forbiddenTermsByPath as $path => $terms) {
            $terms = $this->uniqueTerms($terms);
            if ($path === '' || $terms === []) {
                continue;
            }

            $this->restrictions[] = [
                'path' => $path,
                'terms' => $terms,
                'matcher' => new RulePathMatcher([$path]),
            ];
        }
    }

    /**
     * Returns every restriction applying to one analyzed file.
     *
     * @return list<array{path: string, terms: list<string>}>
     */
    public function matching(string $filePath): array
    {
        $matching = [];
        foreach ($this->restrictions as $restriction) {
            if (!$restriction['matcher']->matches($filePath)) {
                continue;
            }

            $matching[] = [
                'path' => $restriction['path'],
                'terms' => $restriction['terms'],
            ];
        }

        return $matching;
    }

    /**
     * Removes empty and case-insensitive duplicate terms while preserving policy order.
     *
     * @param list<string> $terms
     * @return list<string>
     */
    public function uniqueTerms(array $terms): array
    {
        $unique = [];
        $seen = [];
        foreach ($terms as $term) {
            $key = strtolower($term);
            if ($term === '' || isset($seen[$key])) {
                continue;
            }

            $seen[$key] = true;
            $unique[] = $term;
        }

        return $unique;
    }
}
