        if (!$classType->canCallMethods()->yes()) {
            return [array_merge($errors, [RuleErrorBuilder::message(sprintf('Cannot call static method %s() on %s.', $methodName, $typeForDescribe->describe(VerbosityLevel::typeOnly())))->line($astName->getStartLine())->identifier('staticMethod.nonObject')->build()]), null];
        }
        if (!$classType->hasMethod($methodName)->yes()) {
