            }
        }
        if (!$scope->canCallMethod($method)) {
            $errors = array_merge($errors, [RuleErrorBuilder::message(sprintf('Call to %s %s %s() of class %s.', $method->isPrivate() ? 'private' : 'protected', $method->isStatic() ? 'static method' : 'method', $method->getName(), $method->getDeclaringClass()->getDisplayName()))->line($astName->getStartLine())->identifier(sprintf('staticMethod.%s', $method->isPrivate() ? 'private' : 'protected'))->build()]);
        }
        if ($isAbstract) {
            return [[RuleErrorBuilder::message(sprintf('Cannot call abstract%s method %s::%s().', $method->isStatic() ? ' static' : '', $method->getDeclaringClass()->getDisplayName(), $method->getName()))->line($astName->getStartLine())->identifier(sprintf('%s.callToAbstract', $method->isStatic() ? 'staticMethod' : 'method'))->build()], $method];
        }
        $lowercasedMethodName = SprintfHelper::escapeFormatString(sprintf('%s %s', $method->isStatic() ? 'static method' : 'method', $method->getDeclaringClass()->getDisplayName() . '::' . $method->getName() . '()'));
        if ($this->checkFunctionNameCase && $method->getName() !== $methodName) {
            $errors[] = RuleErrorBuilder::message(sprintf('Call to %s with incorrect case: %s', $lowercasedMethodName, $methodName))->line($astName->getStartLine())->identifier('staticMethod.nameCase')->build();
        }
        return [$errors, $method];
    }
