/**
 * @covers \Toolkit\PhpStan\Extension\RedundantDiagnostic\DirectThrowDiagnosticPolicy
 * @uses \Toolkit\PhpStan\Rule\ExceptionHandling\ThrowSite
 * @uses \Toolkit\PhpStan\Rule\ExceptionHandling\ThrowSiteCollector
