@@ -0,0 +1,94 @@
+<?php
+
+declare(strict_types=1);
+
+namespace Toolkit\PhpStan\Extension\RedundantDiagnostic;
+
+use PhpParser\Node;
+use PHPStan\Analyser\Error;
+use PHPStan\Analyser\IgnoreErrorExtension;
+use PHPStan\Analyser\Scope;
+
+/**
+ * Suppresses PHPStan diagnostics made redundant by enabled toolkit rules.
+ */
+final class RedundantDiagnosticErrorExtension implements IgnoreErrorExtension
+{
+    /** @readonly */
+    private MemberDiagnosticPolicy $memberDiagnosticPolicy;
+
+    /** @readonly */
+    private TestControlFlowDiagnosticPolicy $testControlFlowDiagnosticPolicy;
+
+    /** @readonly */
+    private DirectThrowDiagnosticPolicy $directThrowDiagnosticPolicy;
+
+    /** @readonly */
+    private RestrictedTestClassPolicy $restrictedTestClassPolicy;
+
+    /**
+     * Creates the extension from toolkit rule switches and dominance policies.
+     *
+     * @param list<string> $testNamespacePrefixes
+     * @param list<string> $restrictedTestNamespacePrefixes
+     */
+    public function __construct(
+        array $testNamespacePrefixes,
+        array $restrictedTestNamespacePrefixes,
+        /** @readonly */
+        private bool $noNonPublicMethod,
+        /** @readonly */
+        private bool $noPrivateMethodInTestClass,
+        /** @readonly */
+        private bool $noPropertyInTestClass,
+        /** @readonly */
+        private bool $noClassConstantInTestClass,
+        /** @readonly */
+        private bool $noControlFlowInTestMethod,
+        /** @readonly */
+        private bool $requireThrowsTagOnDirectThrow,
+        ?MemberDiagnosticPolicy $memberDiagnosticPolicy = null,
+        ?TestControlFlowDiagnosticPolicy $testControlFlowDiagnosticPolicy = null,
+        ?DirectThrowDiagnosticPolicy $directThrowDiagnosticPolicy = null,
+        ?RestrictedTestClassPolicy $restrictedTestClassPolicy = null,
+    ) {
+        $this->memberDiagnosticPolicy = $memberDiagnosticPolicy ?? new MemberDiagnosticPolicy();
+        $this->testControlFlowDiagnosticPolicy = $testControlFlowDiagnosticPolicy ?? new TestControlFlowDiagnosticPolicy();
+        $this->directThrowDiagnosticPolicy = $directThrowDiagnosticPolicy ?? new DirectThrowDiagnosticPolicy();
+        $this->restrictedTestClassPolicy = $restrictedTestClassPolicy ?? new RestrictedTestClassPolicy(
+            $testNamespacePrefixes,
+            $restrictedTestNamespacePrefixes,
+        );
+    }
+
+    /**
+     * Reports whether an enabled toolkit rule provides the sole actionable diagnostic.
+     */
+    public function shouldIgnore(Error $error, Node $node, Scope $scope): bool
+    {
+        $identifier = $error->getIdentifier();
+        $classReflection = $scope->getClassReflection();
+        $restrictedTestClass = $this->restrictedTestClassPolicy->isRestricted(
+            $classReflection === null ? null : $classReflection->getName(),
+        );
+        if ($this->memberDiagnosticPolicy->isRedundant(
+            $identifier,
+            $restrictedTestClass,
+            $this->noNonPublicMethod,
+            $this->noPrivateMethodInTestClass,
+            $this->noPropertyInTestClass,
+            $this->noClassConstantInTestClass,
+        )) {
+            return true;
+        }
+
+        if ($this->noControlFlowInTestMethod
+            && $this->testControlFlowDiagnosticPolicy->isRedundant($node, $scope, $restrictedTestClass)
+        ) {
+            return true;
+        }
+
+        return $this->requireThrowsTagOnDirectThrow
+            && $this->directThrowDiagnosticPolicy->isRedundant($identifier, $error->getLine(), $node);
+    }
+}
diff --git a/src/PhpStan/Extension/RedundantDiagnostic/RestrictedTestClassPolicy.php b/src/PhpStan/Extension/RedundantDiagnostic/RestrictedTestClassPolicy.php
new file mode 100644
index 0000000..b19f7bb
--- /dev/null
+++ b/src/PhpStan/Extension/RedundantDiagnostic/RestrictedTestClassPolicy.php
@@ -0,0 +1,67 @@
+<?php
+
+declare(strict_types=1);
+
+namespace Toolkit\PhpStan\Extension\RedundantDiagnostic;
+
+use function array_map;
+use function rtrim;
+use function str_starts_with;
+
+/**
+ * Identifies class names covered by the toolkit's restricted test policy.
+ */
+final class RestrictedTestClassPolicy
+{
+    /** @var list<string> */
+    private array $testNamespacePrefixes;
+
+    /** @var list<string> */
+    private array $restrictedTestNamespacePrefixes;
+
+    /**
+     * Creates the policy from test and restricted namespace prefixes.
+     *
+     * @param list<string> $testNamespacePrefixes
+     * @param list<string> $restrictedTestNamespacePrefixes
+     */
+    public function __construct(
+        array $testNamespacePrefixes = ['Tests'],
+        array $restrictedTestNamespacePrefixes = ['Tests\\Unit', 'Tests\\Integration'],
+    ) {
+        $normalize = static fn (string $prefix): string => rtrim($prefix, '\\') . '\\';
+        $this->testNamespacePrefixes = array_map($normalize, $testNamespacePrefixes);
+        $this->restrictedTestNamespacePrefixes = array_map($normalize, $restrictedTestNamespacePrefixes);
+    }
+
+    /**
+     * Reports whether a class name belongs to both configured namespace sets.
+     */
+    public function isRestricted(?string $className): bool
+    {
+        if ($className === null) {
+            return false;
+        }
+
+        $className = ltrim($className, '\\');
+        $isTestClass = false;
+        foreach ($this->testNamespacePrefixes as $prefix) {
+            if (str_starts_with($className, $prefix)) {
+                $isTestClass = true;
+                break;
+            }
+        }
+
+        if (!$isTestClass) {
+            return false;
+        }
+
+        foreach ($this->restrictedTestNamespacePrefixes as $prefix) {
+            if (str_starts_with($className, $prefix)) {
+                return true;
+            }
+        }
+
+        return false;
+    }
+}
diff --git a/src/PhpStan/Extension/RedundantDiagnostic/TestControlFlowDiagnosticPolicy.php b/src/PhpStan/Extension/RedundantDiagnostic/TestControlFlowDiagnosticPolicy.php
new file mode 100644
index 0000000..66eff62
--- /dev/null
+++ b/src/PhpStan/Extension/RedundantDiagnostic/TestControlFlowDiagnosticPolicy.php
@@ -0,0 +1,65 @@
+<?php
+
+declare(strict_types=1);
+
+namespace Toolkit\PhpStan\Extension\RedundantDiagnostic;
+
+use PhpParser\Node;
+use PHPStan\Analyser\Scope;
+
+use function str_ends_with;
+use function str_starts_with;
+
+/**
+ * Identifies diagnostics about control-flow constructs prohibited in test methods.
+ */
+final class TestControlFlowDiagnosticPolicy
+{
+    /**
+     * Reports whether the diagnostic node belongs to prohibited test-method control flow.
+     */
+    public function isRedundant(Node $node, Scope $scope, bool $restrictedTestClass): bool
+    {
+        if (!$restrictedTestClass || !$this->isTestMethod($scope)) {
+            return false;
+        }
+
+        return $node instanceof Node\Stmt\If_
+            || $node instanceof Node\Stmt\ElseIf_
+            || $node instanceof Node\Stmt\For_
+            || $node instanceof Node\Stmt\Foreach_
+            || $node instanceof Node\Stmt\While_
+            || $node instanceof Node\Stmt\Do_
+            || $node instanceof Node\Stmt\Switch_
+            || $node instanceof Node\Expr\Match_;
+    }
+
+    /**
+     * Reports whether the current reflected method is a PHPUnit test.
+     */
+    public function isTestMethod(Scope $scope): bool
+    {
+        $methodName = $scope->getFunctionName();
+        if ($methodName === null) {
+            return false;
+        }
+
+        if (str_starts_with($methodName, 'test')) {
+            return true;
+        }
+
+        $classReflection = $scope->getClassReflection();
+        if ($classReflection === null || !$classReflection->hasNativeMethod($methodName)) {
+            return false;
+        }
+
+        foreach ($classReflection->getNativeMethod($methodName)->getAttributes() as $attribute) {
+            $name = $attribute->getName();
+            if ($name === 'Test' || str_ends_with($name, '\\Test')) {
+                return true;
+            }
+        }
+
+        return false;
+    }
+}
